def float_bits(value: float) -> int:
    return struct.unpack(">Q", struct.pack(">d", value))[0]


def float_from_bits(bits: int) -> float:
    return struct.unpack(">d", struct.pack(">Q", bits))[0]


def reachable_rate_fractions() -> tuple[Fraction, ...]:
    """Return the exact rate domain reachable by the frozen 192 controllers."""
    from .controllers import CONTROLLER_REGISTRY

    coefficient_triples = set()
    for controller in CONTROLLER_REGISTRY:
        coefficient_triples.add(
            (controller.alpha_short, controller.beta_short, controller.gamma_short)
        )
        coefficient_triples.add(
            (controller.alpha_long, controller.beta_long, controller.gamma_long)
        )
    rates: set[Fraction] = set()
    for scored_ticks in (32, 128):
        for alpha, beta, gamma in coefficient_triples:
            for scored_index in range(scored_ticks):
                remaining = Fraction(scored_ticks - scored_index, scored_ticks)
                for age_ticks in range(scored_index + 1):
                    age = min(Fraction(age_ticks, 128), Fraction(1))
                    value = (
                        Fraction(alpha, 8)
                        + Fraction(beta, 8) * (remaining - Fraction(1, 2))
                        + Fraction(gamma, 8) * (age - Fraction(1, 2))
                    )
                    rates.add(min(max(value, Fraction(0)), Fraction(7, 8)))
    ordered = tuple(sorted(rates))
    if len(ordered) != 456 or max(q.denominator for q in ordered) != 1024:
        raise AssertionError("reachable event-rate domain differs from the frozen table")
    return ordered


def event_transform_bits(q: Fraction | int) -> tuple[int, int, int]:
    exact = Fraction(q)
    scaled = exact * 1024
    if scaled.denominator != 1 or not 0 <= scaled.numerator <= 896:
        raise ValueError("q is outside the frozen dyadic event-transform table")
    index = scaled.numerator
    return float_bits(float(exact)), _LAMBDA_BITS[index], _EVENT_BITS[index]


def event_transform(q: Fraction | int) -> tuple[float, float, float]:
    q_bits, lambda_bits, event_bits = event_transform_bits(q)
    return (
        float_from_bits(q_bits),
        float_from_bits(lambda_bits),
        float_from_bits(event_bits),
    )
